// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address newOwner, address caller) public {
        vm.prank(caller);
        bool ok;
        try c.setOwner(newOwner) { ok = true; } catch { ok = false; }
        if (ok && caller != address(this)) {
            // admin is the deployer (address(this)); only admin calls succeed
            assertTrue(false, "unreachable");
        }
        vm.prank(address(this));
        c.setOwner(newOwner);
        assertTrue(c.owner() == newOwner, "owner must equal the requested new owner");
    }
}
